    const sws = M.all(hass, 'switch', (s, id) => !osSet.has(id) && KW.test(T(id)) && (inA(id) || !explicit) && !/regn|rain|anlegg|controller|enabled|hopp|skip|pause|basseng|pool/.test(T(id)));
